package dev.grimholt.server.api;
import dev.grimholt.api.*; import java.util.List; import java.util.concurrent.*;
public final class DefaultEventBus implements EventBus { private final ConcurrentHashMap<Class<?>,CopyOnWriteArrayList<EventListener<?>>> listeners=new ConcurrentHashMap<>(); public <E extends Event> void register(Class<E> t,EventListener<? super E> l){listeners.computeIfAbsent(t,k->new CopyOnWriteArrayList<>()).addIfAbsent(l);} public <E extends Event> boolean unregister(Class<E> t,EventListener<? super E> l){var x=listeners.get(t);return x!=null&&x.remove(l);} @SuppressWarnings("unchecked") public <E extends Event> void post(E e){var x=listeners.get(e.getClass());if(x==null)return;for(var l:List.copyOf(x))try{((EventListener<E>)l).onEvent(e);}catch(Throwable ignored){}} public void clear(){listeners.clear();}}
